// AUTO-GENERATED by Bloxks — DO NOT EDIT. Local reminders scheduled on the phone (no server).
// Usage (texts come from the app's notification list, notifications/catalog.ts):
//   import { ensureNotificationPermission, scheduleReminder, cancelReminder } from '../zzz/notifications'
//   import { notificationContent } from '../notifications/catalog'
//   const perm = await ensureNotificationPermission()
//   if (perm === 'granted') await scheduleReminder({ id: 'water', ...notificationContent('water', { locale: appLocale() }), repeat: 'daily', date })
//   await cancelReminder('water')   // the same id replaces / cancels that reminder
// repeat: 'daily' or 'weekly' (at date's time / weekday), or { everySeconds: 3600 } (60 s minimum).
// (appLocale comes from ../zzz/i18n when the app is multilingual.)
// In the browser preview the permission alert and the banners are SIMULATED inside the preview
// phone (never a browser notification); on the phone they are real system notifications.
// Push (remote, server-sent) lives in zzz/push.ts. Never throws.
import * as Notifications from 'expo-notifications'
import { Platform } from 'react-native'

// Same handler as zzz/push.ts (whichever is imported first, same result).
try {
  Notifications.setNotificationHandler({
    handleNotification: async () => ({
      shouldShowBanner: true,
      shouldShowList: true,
      shouldPlaySound: true,
      shouldSetBadge: false,
    }),
  })
} catch {}

export type ReminderResult =
  | { ok: true; id: string }
  | { ok: false; reason: 'denied' | 'invalid' | 'error'; message: string }

/** True where the notification will really reach the system tray. */
export const NOTIFICATIONS_ARE_REAL = Platform.OS !== 'web'

export async function ensureNotificationPermission(): Promise<'granted' | 'denied'> {
  try {
    const current = await Notifications.getPermissionsAsync()
    if (current.granted) return 'granted'
    const asked = await Notifications.requestPermissionsAsync()
    return asked.granted ? 'granted' : 'denied'
  } catch {
    return 'denied'
  }
}

/**
 * Schedules a local reminder. `id` (optional, stable): scheduling the same id
 * again replaces the previous reminder, and cancelReminder(id) cancels it.
 */
export async function scheduleReminder(input: {
  id?: string
  title: string
  body?: string
  inSeconds?: number
  date?: Date
  repeat?: 'daily' | 'weekly' | { everySeconds: number }
}): Promise<ReminderResult> {
  try {
    const permission = await ensureNotificationPermission()
    if (permission !== 'granted') {
      return { ok: false, reason: 'denied', message: 'Notifications refusées — active-les dans les réglages. · Notifications denied — enable them in settings.' }
    }
    const id = typeof input.id === 'string' && input.id.trim() ? input.id.trim() : undefined
    const date = input.date instanceof Date && !Number.isNaN(input.date.getTime()) ? input.date : undefined
    const repeat = input.repeat
    let trigger: Notifications.NotificationTriggerInput
    if (repeat && typeof repeat === 'object') {
      const every = Number(repeat.everySeconds)
      if (!(every > 0)) return { ok: false, reason: 'invalid', message: 'repeat.everySeconds must be a number of seconds (60 minimum).' }
      trigger = { type: Notifications.SchedulableTriggerInputTypes.TIME_INTERVAL, seconds: Math.max(60, Math.round(every)), repeats: true }
    } else if (repeat === 'daily' && date) {
      trigger = { type: Notifications.SchedulableTriggerInputTypes.DAILY, hour: date.getHours(), minute: date.getMinutes() }
    } else if (repeat === 'weekly' && date) {
      trigger = { type: Notifications.SchedulableTriggerInputTypes.WEEKLY, weekday: date.getDay() + 1, hour: date.getHours(), minute: date.getMinutes() }
    } else if (date) {
      if (date.getTime() <= Date.now()) return { ok: false, reason: 'invalid', message: 'scheduleReminder: date is in the past.' }
      trigger = { type: Notifications.SchedulableTriggerInputTypes.DATE, date }
    } else if (typeof input.inSeconds === 'number' && input.inSeconds > 0) {
      trigger = { type: Notifications.SchedulableTriggerInputTypes.TIME_INTERVAL, seconds: Math.max(1, Math.round(input.inSeconds)) }
    } else {
      return { ok: false, reason: 'invalid', message: 'scheduleReminder needs inSeconds, date, or repeat: { everySeconds }.' }
    }
    // Same id: the new reminder replaces the old one.
    if (id) await cancelReminder(id)
    const scheduled = await Notifications.scheduleNotificationAsync({
      ...(id ? { identifier: id } : {}),
      content: { title: input.title, body: input.body },
      trigger,
    })
    return { ok: true, id: scheduled }
  } catch (e) {
    return { ok: false, reason: 'error', message: e instanceof Error ? e.message : String(e) }
  }
}

/** Cancels the reminder with this id (the `id` given to scheduleReminder, or the one it returned). */
export async function cancelReminder(id: string): Promise<void> {
  try { await Notifications.cancelScheduledNotificationAsync(id) } catch {}
}

/** Cancels every reminder scheduled by this app. */
export async function cancelAllReminders(): Promise<void> {
  try { await Notifications.cancelAllScheduledNotificationsAsync() } catch {}
}
